B.push(
{id:"M2-01",m:2,q:"¿Cuál es el objetivo principal del lavado de activos?",o:["Simular la licitud del origen de los fondos","Evadir el pago de impuestos","Financiar organizaciones terroristas","Obtener financiamiento a tasas más bajas"],a:0,e:"El lavado busca dar apariencia lícita a fondos de origen delictivo. La evasión puede ser el delito precedente, no el objetivo.",r:"M2 · P1"},
{id:"M2-02",m:2,q:"¿Cuál de las siguientes NO es una etapa del lavado de activos?",o:["Colocación","Estratificación","Fiscalización","Integración"],a:2,e:"Las tres etapas GAFI son colocación, estratificación (o diversificación) e integración. La fiscalización no es una de ellas.",r:"M2 · P2"},
{id:"M2-03",m:2,q:"¿Qué diferencia principal existe entre lavado de activos y financiamiento del terrorismo?",o:["El financiamiento del terrorismo puede usar fondos de origen lícito","El lavado siempre involucra efectivo y el terrorismo no","El financiamiento del terrorismo no es delito en Argentina","El lavado no requiere reporte a la UIF"],a:0,e:"Pregunta clásica: en el FT el origen de los fondos puede ser lícito; lo ilícito es el destino.",r:"M2 · P3"},
{id:"M2-04",m:2,q:"¿Quién es la autoridad de aplicación de la Ley 25.246?",o:["El Ministerio de Justicia","El BCRA","La Unidad de Información Financiera (UIF)","El Ministerio Público Fiscal"],a:2,e:"La UIF es la autoridad de aplicación de la Ley 25.246; la CNV es organismo supervisor sectorial en el mercado de capitales.",r:"M2 · P4"},
{id:"M2-48",m:2,q:"Según la Resolución UIF 56/2024, ¿cuál es el plazo para reportar una operación sospechosa?",o:["5 días hábiles","7 días hábiles","15 días corridos","30 días corridos"],a:1,e:"La guía da 7 días hábiles como plazo del ROS bajo la Res. UIF 56/2024. Ojo: el caso de FT con listados ONU es distinto (sin demora).",r:"M2 · P5"},
{id:"M2-49",m:2,q:"¿Qué norma establece la obligación de reportar operaciones sospechosas?",o:["Resolución UIF 192/2024","Resolución UIF 72/2023","Resolución UIF 29/2013","Resolución UIF 3/2014"],a:2,e:"La Res. UIF 29/2013 regula la obligación de reportar hechos u operaciones sospechosas. La 192/2024 es PEP y la 72/2023, supervisión.",r:"M2 · P6"},
{id:"M2-50",m:2,q:"¿Cuál de los siguientes es un sujeto obligado según la Ley 25.246?",o:["Los Agentes de Liquidación y Compensación","Los Agentes Productores","Los comitentes personas humanas","Los ALyC Participantes Directos"],a:0,e:"Los ALyC son sujetos obligados. Los Agentes Productores y los ALyC Participantes Directos, en cambio, no lo son.",r:"M2 · P7"},
{id:"M2-51",m:2,q:"¿Qué organismo supervisa el cumplimiento de la normativa de prevención en el mercado de capitales?",o:["El Banco Central (BCRA)","El mercado donde opera el agente","La Comisión Nacional de Valores","ARCA (ex AFIP)"],a:2,e:"La CNV es el organismo supervisor sectorial del mercado de capitales; la UIF es la autoridad de aplicación de la Ley 25.246.",r:"M2 · P8"},
{id:"M2-52",m:2,q:"¿Qué significa PEP según la normativa UIF?",o:["Perfil de Exposición Patrimonial","Persona Especialmente Protegida","Participante en Emisiones Públicas","Persona Expuesta Políticamente"],a:3,e:"PEP = Persona Expuesta Políticamente; su definición está en la Res. UIF 192/2024.",r:"M2 · P9"},
{id:"M2-06",m:2,q:"¿Cuál es la finalidad de las 40 Recomendaciones del FATF-GAFI?",o:["Establecer estándares internacionales contra el lavado de activos y el financiamiento del terrorismo","Uniformar los estados financieros a nivel global","Regular los mercados de derivados","Fijar sanciones penales mínimas para los países miembros"],a:0,e:"Las 40 Recomendaciones son el estándar internacional contra el LA/FT que siguen los países.",r:"M2 · P10"},
{id:"M2-53",m:2,q:"¿Cuál es la autoridad encargada de dictar normas sobre prevención de lavado en el mercado de capitales?",o:["La Comisión Nacional de Valores","El Banco Central (BCRA)","El Ministerio de Justicia","Bolsas y Mercados Argentinos (BYMA)"],a:0,e:"La CNV dicta las normas de prevención para el mercado de capitales (Normas CNV, Título XI).",r:"M2 · P11"},
{id:"M2-08",m:2,q:"¿Qué organismo centraliza la recepción de Reportes de Operaciones Sospechosas?",o:["La CNV","El BCRA","El Ministerio de Justicia","La UIF"],a:3,e:"Los ROS se centralizan en la UIF, aunque el supervisor sectorial del mercado de capitales sea la CNV.",r:"M2 · P12"},
{id:"M2-54",m:2,q:"¿Cuál es la finalidad del Decreto 918/2012?",o:["Reglamentar la Ley 26.831 de Mercado de Capitales","Reglamentar la Ley 25.246","Aprobar las Normas CNV (N.T. 2013)","Fijar los plazos de los Reportes de Operaciones Sospechosas"],a:1,e:"El Decreto 918/2012 reglamenta la Ley 25.246. Los plazos del ROS salen de la Res. UIF 56/2024.",r:"M2 · P13"},
{id:"M2-83",m:2,q:"¿Qué característica define al financiamiento del terrorismo?",o:["Sólo puede financiarse con fondos provenientes del narcotráfico","Requiere siempre la intervención de una organización extranjera","Puede usar fondos lícitos","Sus fondos deben pasar siempre por la etapa de integración"],a:2,e:"Lo que distingue al FT es que los fondos pueden tener origen lícito: lo ilícito está en el destino que se les da.",r:"M2 · P14"},
{id:"M2-84",m:2,q:"¿Cuál es el objetivo de las 40 Recomendaciones del GAFI?",o:["Armonizar las normas contables internacionales de las entidades financieras","Crear un tribunal internacional para juzgar los delitos de lavado","Fijar las tasas de interés de referencia de los países miembros","Establecer estándares internacionales contra Lavado de Activos y Financiación del Terrorismo"],a:3,e:"El GAFI fija, con sus 40 Recomendaciones, los estándares internacionales contra el LA/FT; no es un tribunal ni un regulador contable.",r:"M2 · P15"},
{id:"M2-09",m:2,q:"¿Qué norma define a las Personas Expuestas Políticamente (PEP)?",o:["Resolución UIF 29/2013","Resolución UIF 78/2023","Resolución UIF 192/2024","Resolución UIF 56/2024"],a:2,e:"PEP = Resolución UIF 192/2024. No confundir con 29/2013 (ROS y congelamiento) ni 78/2023 (mercado de capitales).",r:"M2 · P16"},
{id:"M2-55",m:2,q:"¿Cuál es la sanción por incumplir la obligación de reportar operaciones sospechosas?",o:["Sólo sanción administrativa","Sólo sanción penal","Sanción penal y administrativa","Un apercibimiento, sin multa"],a:2,e:"El incumplimiento del deber de reportar tiene sanción penal y administrativa.",r:"M2 · P17"},
{id:"M2-05",m:2,q:"¿Qué etapa del lavado implica mover fondos para ocultar su origen?",o:["Colocación","Estratificación","Integración","Consolidación"],a:1,e:"Colocación = ingreso al sistema. Estratificación = capas de operaciones para borrar el rastro. Integración = uso como si fueran lícitos.",r:"M2 · P18"},
{id:"M2-85",m:2,q:"¿Qué plazo tiene un sujeto obligado para conservar documentación respaldatoria?",o:["1 año","3 años","5 años","Hasta la próxima inspección de la UIF"],a:2,e:"La guía responde 5 años. Ojo: para esta pregunta la guía da 5 años; en la P60 (documentación del cliente) da 10 años desde que termina la relación, así que respondé cada una con su número.",r:"M2 · P19"},
{id:"M2-56",m:2,q:"¿Cuál es el objetivo del Reporte de Operaciones Sospechosas?",o:["Informar a la CNV las operaciones de mayor monto","Advertir al cliente que su operatoria está bajo análisis","Bloquear automáticamente los fondos del cliente","Comunicar operaciones sospechosas a la UIF"],a:3,e:"El ROS sirve para comunicar a la UIF las operaciones sospechosas. Nunca se le revela al cliente.",r:"M2 · P20"},
{id:"M2-57",m:2,q:"¿Qué norma establece la obligación de identificar al cliente?",o:["Resolución UIF 29/2013","Resolución UIF 192/2024","Resolución UIF 72/2023","Resolución UIF 3/2014"],a:3,e:"Según la guía, la obligación de identificar al cliente surge de la Res. UIF 3/2014.",r:"M2 · P21"},
{id:"M2-86",m:2,q:"¿Qué autoridad supervisa el cumplimiento de la normativa UIF en el mercado de capitales?",o:["Comisión Nacional de Valores","Banco Central (BCRA)","Bolsas y Mercados Argentinos (BYMA)","Ministerio de Economía"],a:0,e:"La CNV es el organismo supervisor sectorial: controla que los sujetos obligados del mercado de capitales cumplan la normativa UIF.",r:"M2 · P22"},
{id:"M2-58",m:2,q:"¿Qué tipo de operaciones deben ser reportadas como sospechosas?",o:["Las que no se ajustan al perfil del cliente","Todas las que superan un monto fijo determinado por la UIF","Todas las operaciones de clientes PEP","Todas las operaciones realizadas en efectivo"],a:0,e:"Lo que dispara la sospecha es el desajuste con el perfil del cliente, no un umbral de monto ni la condición de PEP.",r:"M2 · P23"},
{id:"M2-59",m:2,q:"¿Qué norma establece los plazos para Reportes de Operaciones Sospechosas?",o:["Resolución UIF 3/2014","Resolución UIF 56/2024","Resolución UIF 72/2023","Resolución UIF 192/2024"],a:1,e:"La Res. UIF 56/2024 es la de plazos para la realización de ROS.",r:"M2 · P24"},
{id:"M2-60",m:2,q:"¿Qué organismo dicta normas sobre prevención de Lavado de Activos y Financiación del Terrorismo en entidades financieras?",o:["El Banco Central (BCRA)","ARCA (ex AFIP)","La UIF","El Ministerio de Economía"],a:2,e:"Según la guía, las normas de prevención de LA/FT para entidades financieras las dicta la UIF.",r:"M2 · P25"},
{id:"M2-61",m:2,q:"¿Qué norma regula la supervisión del cumplimiento de la normativa UIF?",o:["Resolución UIF 72/2023","Resolución UIF 29/2013","Resolución UIF 56/2024","Resolución UIF 192/2024"],a:0,e:"La Res. UIF 72/2023 reglamenta el procedimiento de supervisión del cumplimiento de la normativa UIF.",r:"M2 · P26"},
{id:"M2-10",m:2,q:"¿Qué norma regula la prevención de Lavado de Activos y la Financiación del Terrorismo en el mercado de capitales?",o:["Normas CNV Título IV","Normas CNV Título XI","Normas CNV Título XIII","Normas CNV Título XVI"],a:1,e:"Normas CNV, Título XI: prevención del lavado de activos y financiación del terrorismo.",r:"M2 · P27"},
{id:"M2-62",m:2,q:"¿Qué norma regula la obligación de informar PEP?",o:["Resolución UIF 29/2013","Resolución UIF 56/2024","Ley 26.831","Decreto 918/2012"],a:3,e:"Ojo con la distinción de la guía: la definición de PEP está en la Res. UIF 192/2024, pero la obligación de informarlas la ubica en el Decreto 918/2012.",r:"M2 · P28"},
{id:"M2-63",m:2,q:"¿Qué norma establece la obligación de reportar operaciones sospechosas en el mercado de capitales?",o:["Resolución UIF 192/2024","Resolución UIF 72/2023","Resolución UIF 3/2014","Resolución UIF 78/2023"],a:3,e:"Para el mercado de capitales, la norma es la Res. UIF 78/2023. La obligación general de reportar está en la 29/2013.",r:"M2 · P29"},
{id:"M2-64",m:2,q:"¿Qué norma incorpora la figura del encubrimiento y lavado como delito penal?",o:["Ley 26.831","Decreto 918/2012","Ley 25.246","Resolución UIF 29/2013"],a:2,e:"La Ley 25.246 (lavado de activos de origen delictivo) modificó el Código Penal e incorporó encubrimiento y lavado como delito.",r:"M2 · P30"},
{id:"M2-87",m:2,q:"¿Cuál de éstos no es uno de los pilares del Programa de Prevención de Lavado de Activos y Financiamiento al Terrorismo (PLAFT) para un Agente?",o:["La designación de un Oficial de Cumplimiento","La recomendación de los activos en los que podrá operar el cliente, conforme el riesgo que éste desee asumir","El legajo y la debida diligencia de cada cliente según su nivel de riesgo","La capacitación del personal en materia de prevención de LA/FT"],a:1,e:"Recomendar activos según el apetito de riesgo del cliente es asesoramiento de inversión, no un pilar del programa PLAFT; el oficial de cumplimiento, el legajo y la capacitación sí lo son.",r:"M2 · P31"},
{id:"M2-88",m:2,q:"¿Cuál de las siguientes opciones contempla las tres etapas del Lavado de Activos según GAFI?",o:["Colocación, fiscalización e integración","Captación, estratificación y consolidación","Colocación, diversificación o estratificación e integración","Ocultamiento, transferencia y reporte"],a:2,e:"Las tres etapas del GAFI son colocación, diversificación (o estratificación) e integración.",r:"M2 · P32"},
{id:"M2-11",m:2,q:"¿Cuándo se considera que un hecho u operación es sospechosa de lavado de activos?",o:["Cuando la operación, tentada o realizada, por sus características o por no poder justificarse la inusualidad tras el análisis del Sujeto Obligado, genera sospecha o motivos razonables de que los fondos provienen de un ilícito penal o se vinculan con LA/FT","Cuando supera un monto fijado por la UIF","Cuando el cliente se niega a firmar el legajo","Cuando interviene un cliente extranjero"],a:0,e:"No hay umbral de monto: lo determinante es la inusualidad no justificada tras el análisis del sujeto obligado.",r:"M2 · P33"},
{id:"M2-17",m:2,q:"¿Quién establece formalmente los listados de sanciones financieras dirigidas aplicables en materia de Financiamiento al Terrorismo (por ejemplo, las listas vinculadas a la Resolución 1267)?",o:["El GAFI","La UIF","La Interpol","El Consejo de Seguridad de las Naciones Unidas"],a:3,e:"Las listas (Res. 1267 y sucesivas) las establece el Consejo de Seguridad de la ONU.",r:"M2 · P34"},
{id:"M2-65",m:2,q:"¿Existe plazo máximo para reportar hechos u operaciones sospechosas de financiación de terrorismo, a partir de la operación realizada o tentada?",o:["No, queda a criterio del oficial de cumplimiento","Sí: siempre sin demora alguna, en todos los casos","Sí: 48 horas desde la operación","El establecido en la Ley 27.739 y en las resoluciones UIF pertinentes a cada tipo de Sujeto Obligado, en el marco de la Res. UIF 56/2024"],a:3,e:"Rige el mismo criterio que para lavado. El \"sin demora alguna\" es sólo para personas o bienes designados por el Consejo de Seguridad de la ONU.",r:"M2 · P35"},
{id:"M2-15",m:2,q:"¿Existe plazo máximo para reportar hechos u operaciones sospechosas de lavado de activos, a partir de la operación realizada o tentada?",o:["El establecido en la Ley 27.739 y en las resoluciones emitidas por la UIF pertinentes a cada tipo de Sujeto Obligado, en el marco de la Resolución UIF 56/2024","Sí: 30 días corridos en todos los casos","Sí: al cierre del ejercicio anual del Sujeto Obligado","No hay plazo: queda a criterio del oficial de cumplimiento"],a:0,e:"El plazo surge de la Ley 27.739 y de las resoluciones UIF de cada tipo de sujeto obligado, en el marco de la Res. UIF 56/2024.",r:"M2 · P36"},
{id:"M2-16",m:2,q:"¿Existe plazo para comunicar a la UIF una operación sospechosa de Financiación del Terrorismo cuando los bienes o dinero involucrados, las personas que lleven a cabo la operación o su destinatario o beneficiario se encuentren designados por el Consejo de Seguridad de las Naciones Unidas de conformidad con la Resolución 1267 (1999) y sus sucesivas? (Resolución UIF 29/2013)",o:["Sí, dentro de los 15 días hábiles","Sí, dentro de las 48 horas","Sí, sin demora alguna","No, se informa junto con el reporte sistemático mensual"],a:2,e:"Listados ONU: reporte sin demora alguna. Es el único caso con esa exigencia inmediata.",r:"M2 · P37"},
{id:"M2-89",m:2,q:"¿Qué es el Lavado de Dinero?",o:["Un proceso por el cual se reúnen fondos, lícitos o ilícitos, para financiar actos terroristas","Un proceso por el cual una persona que obtuvo fondos por la comisión de un delito los incorpora a la economía formal, con la finalidad de darles una apariencia lícita","La omisión de declarar ingresos lícitos ante la autoridad tributaria para pagar menos impuestos","El traslado de fondos lícitos al exterior para eludir los controles cambiarios"],a:1,e:"El lavado parte de fondos obtenidos por un delito y busca meterlos en la economía formal con apariencia lícita; juntar fondos para terrorismo es FT.",r:"M2 · P38"},
{id:"M2-12",m:2,q:"¿Qué se entiende por operación inusual?",o:["Toda operación superior a $10.000.000","Operaciones tentadas o realizadas en forma aislada o reiterada, con independencia del monto, que carecen de justificación económica y/o jurídica, y/o no guardan relación con el nivel de riesgo del cliente o su perfil transaccional, y/o se desvían de los usos y costumbres en las prácticas de mercado","Cualquier operación realizada por un PEP","La operación que el cliente ordena por medios no convenidos"],a:1,e:"Inusual ≠ sospechosa: la inusual dispara el análisis; si no se justifica, se convierte en sospechosa y se reporta.",r:"M2 · P39"},
{id:"M2-90",m:2,q:"Algunas de las obligaciones del Oficial de Cumplimiento son:",o:["Aprobar el Manual de Prevención de LA/FT en reemplazo del órgano de administración","Aplicar sanciones administrativas a los clientes que incumplan la normativa de prevención","Autorizar cada operación de los clientes de riesgo alto antes de su concertación","Evaluar y verificar la aplicación de las políticas y procedimientos del Sistema de Prevención de LA/FT, incluyendo el monitoreo de operaciones, la detección oportuna y el Reporte de Operaciones Sospechosas"],a:3,e:"El Oficial de Cumplimiento evalúa y verifica que el sistema PLA/FT se aplique, incluido el monitoreo y el ROS. Las sanciones administrativas las aplica la UIF.",r:"M2 · P40"},
{id:"M2-24",m:2,q:"Considerando que la matriz de riesgo arroja un nivel de riesgo Medio para un cliente, la debida diligencia a aplicar deberá ser:",o:["Aplicar medidas de debida diligencia media y actualizar el legajo cada 3 años","Aplicar medidas de debida diligencia media y actualizar el legajo cada 5 años","Aplicar medidas de debida diligencia reforzada y actualizar el legajo cada 2 años","Aplicar medidas de debida diligencia simplificada y actualizar el legajo cada año"],a:0,e:"Riesgo medio: medidas de debida diligencia media y legajo actualizado cada 3 años.",r:"M2 · P41"},
{id:"M2-26",m:2,q:"Cuando una persona jurídica es Sujeto Obligado en los términos del art. 20 de la Ley 25.246, debe designar un Oficial de Cumplimiento. ¿Quién puede ser designado como tal?",o:["Cualquier empleado con antigüedad mayor a 5 años","El auditor externo de la entidad","Un profesional independiente contratado a tal fin","Un miembro del órgano de administración"],a:3,e:"Debe ser miembro del órgano de administración (director), por la responsabilidad que implica el cargo.",r:"M2 · P42"},
{id:"M2-40",m:2,q:"De acuerdo a las Normas CNV Título XI, los Sujetos Obligados sólo podrán recibir por cliente y por día fondos en efectivo por un monto que no exceda:",o:["El monto establecido en el artículo 1º de la Ley 25.345","El equivalente a 1.000 UVA","$1.000.000","No pueden recibir efectivo en ningún caso"],a:0,e:"El tope remite al art. 1º de la Ley 25.345 (ley antievasión).",r:"M2 · P43"},
{id:"M2-20",m:2,q:"Definición de \"Beneficiario Final\" (Resolución N° 112/2021):",o:["La persona humana que posee como mínimo el 10% del capital o de los derechos de voto de una persona jurídica, fideicomiso, fondo de inversión u otra estructura jurídica, y/o que por otros medios ejerce su control final","El titular registral de la cuenta comitente","El accionista mayoritario, cualquiera sea su porcentaje","El representante legal de la persona jurídica"],a:0,e:"Umbral del 10%, o control final por otros medios. Aplica a sociedades, fideicomisos, fondos y otras estructuras.",r:"M2 · P44"},
{id:"M2-91",m:2,q:"Desde que un hecho u operación es calificada como sospechosa, ¿existe plazo para reportarlo?",o:["No: una vez calificada, el reporte queda a criterio del órgano de administración","Sí: 60 días corridos desde la calificación","El plazo establecido en la Ley 27.739 y en las Resoluciones UIF pertinentes, en el marco de lo dispuesto por la Resolución UIF 56/2024","Sí: hasta la próxima revisión externa independiente"],a:2,e:"La guía remite al plazo de la Ley 27.739 y de las resoluciones UIF pertinentes, en el marco de la Res. UIF 56/2024.",r:"M2 · P45"},
{id:"M2-66",m:2,q:"El comitente A es monotributista y deposita $24.000.000 en su cuenta bancaria, que luego transfiere a su cuenta comitente. Emite la orden de compra de un bono local, siendo el vendedor el agente encargado de la administración de la cuenta, y luego ordena transferirlo a una cuenta de un tercero cuyo titular es su cónyuge. La operación debería ser reportada en cualquiera de los siguientes casos:",o:["Si el cónyuge es cliente de otro agente; si el depósito se hizo en efectivo en la sede del agente; o si el bono tiene legislación extranjera","Si el cónyuge vende los bonos inmediatamente a un precio menor al de las cotizaciones vigentes; si se colocan como garantía de una caución tomadora y los fondos se usan en una operación ajena al perfil de riesgo del cliente; o si se vuelven a transferir a otra cuenta de tercero sin justificación aparente","Sólo si el cónyuge mantiene los bonos en cartera más de un año o los rescata al vencimiento","En ningún caso, porque la transferencia es a un familiar directo y el bono cotiza en un mercado autorizado"],a:1,e:"La guía da esos tres supuestos de reporte: venta inmediata del cónyuge por debajo del precio de mercado, uso como garantía de caución para una operación ajena al perfil, o nueva transferencia a un tercero sin justificación.",r:"M2 · P46"},
{id:"M2-35",m:2,q:"En el marco de las Resoluciones emitidas por la UIF, el legajo del cliente debe contener, entre otras cosas, alguno de los siguientes puntos:",o:["La verificación en el Listado de Terroristas y la identificación del perfil tributario, económico, financiero y patrimonial","Únicamente copia del DNI y constancia de CUIT","El detalle de comisiones pactadas","La calificación de riesgo emitida por un ACR"],a:0,e:"Verificación contra listados + perfil del cliente son la base del \"conozca a su cliente\".",r:"M2 · P47"},
{id:"M2-92",m:2,q:"Respecto de la afirmación \"El Manual de Prevención de LA/FT deberá ser aprobado por el órgano competente, mantenerse actualizado y ser accesible y conocido por todo el personal (no necesariamente en soporte papel), dejando evidencia de su difusión y capacitación\", la respuesta de la guía es:",o:["Sólo en formato digital, sin necesidad de dejar evidencia de su difusión","Sólo en soporte papel y en poder del Oficial de Cumplimiento","En la sede de la UIF, a disposición del organismo","En domicilio físico y de conocimiento del personal"],a:3,e:"La guía contesta \"En domicilio físico y de conocimiento del personal\": el manual tiene que estar en el domicilio y ser conocido por el personal. Es la respuesta oficial aunque encaje raro con la afirmación.",r:"M2 · P48"},
{id:"M2-93",m:2,q:"Respecto de la afirmación \"El Sistema Anti Lavado/Contra Financiación del Terrorismo argentino se compone de la UIF como autoridad de aplicación y de organismos supervisores sectoriales (CNV en mercado de capitales, entre otros), además de autoridades judiciales y de seguridad\", la respuesta de la guía es:",o:["Se encuentra centralizado exclusivamente en la CNV","Cada Sujeto Obligado lo organiza por su cuenta, sin autoridad de aplicación","Está a cargo exclusivamente del Poder Judicial","Se encuentra centralizado exclusivamente en la UIF"],a:3,e:"La guía responde \"Se encuentra centralizado exclusivamente en la UIF\" y es la que vale en el examen, aunque choque con la propia afirmación. Ojo: en otras preguntas la CNV sí aparece como supervisor sectorial.",r:"M2 · P49"},
{id:"M2-14",m:2,q:"El Sujeto Obligado, en el marco del análisis de una posible operación sospechosa, tiene la obligación de:",o:["Notificar al cliente antes de reportar","Abstenerse de revelarlas al cliente o a terceros","Suspender toda operatoria del cliente por 30 días","Informar al mercado donde opera"],a:1,e:"Deber de confidencialidad: nunca se revela al cliente ni a terceros que su operación está en análisis.",r:"M2 · P50"},
{id:"M2-13",m:2,q:"En caso de detectarse operaciones inusuales se deberá como primera medida:",o:["Reportarla de inmediato a la UIF","Cerrar la cuenta del cliente","Profundizar el análisis con el fin de obtener información que corrobore o revierta las operaciones inusuales detectadas","Comunicar la situación al cliente para que la explique por escrito"],a:2,e:"Primero se profundiza el análisis para confirmar o descartar la inusualidad; recién después se decide si se reporta.",r:"M2 · P51"},
{id:"M2-25",m:2,q:"En el caso de tener un cliente extranjero que se declare como PEP, el Sujeto Obligado debe:",o:["Rechazar la apertura de la cuenta","Segmentarlo como de Riesgo Alto","Aplicar debida diligencia simplificada por tratarse de un funcionario","Reportarlo automáticamente como operación sospechosa"],a:1,e:"Ser PEP no impide operar: obliga a segmentarlo como riesgo alto.",r:"M2 · P52"},
{id:"M2-41",m:2,q:"La aplicación de sanciones administrativas a los sujetos obligados del Mercado de Capitales por incumplimiento a las obligaciones en materia de PLA/FT contenidas en la Ley 27.739 y las Resoluciones UIF:",o:["Las efectúa la CNV","Las efectúa el BCRA","Las efectúa el mercado donde opera el agente","Las efectúa la Unidad de Información Financiera"],a:3,e:"Trampa frecuente: la CNV supervisa, pero las sanciones administrativas por PLA/FT las aplica la UIF.",r:"M2 · P53"},
{id:"M2-31",m:2,q:"La Autoevaluación de Riesgo para un Sujeto Obligado inscripto en la categoría de Agente de Negociación podrá realizarse (Resolución UIF 78/2023):",o:["Cada seis meses","Cada dos años","Cada tres años","Sólo al inicio de la actividad"],a:1,e:"Cada dos años, igual que para el Agente Asesor Global de Inversión.",r:"M2 · P54"},
{id:"M2-32",m:2,q:"El Informe Técnico de Autoevaluación de Riesgos deberá cumplir con los siguientes requisitos:",o:["Ser aprobado por el órgano de administración o máxima autoridad del S.O., conservarse, ser actualizado con la periodicidad que indique la normativa y enviarse a la UIF y a la CNV","Ser aprobado por la asamblea de accionistas y archivarse sin necesidad de actualización","Presentarse únicamente ante la CNV, sin intervención del órgano de administración","Publicarse en la Autopista de la Información Financiera para conocimiento del público"],a:0,e:"Aprobación del órgano de administración o máxima autoridad, conservación, actualización periódica y envío a UIF y CNV.",r:"M2 · P55"},
{id:"M2-07",m:2,q:"La Recomendación 1 del GAFI hace referencia al enfoque que deben tomar los países para las medidas de prevención de LA/FT. Este enfoque debe estar basado en:",o:["El monto de las operaciones","Riesgo","La nacionalidad del cliente","El tipo de instrumento negociado"],a:1,e:"Enfoque basado en riesgo: se asignan recursos y controles según el nivel de riesgo detectado.",r:"M2 · P56"},
{id:"M2-30",m:2,q:"La Revisión Externa Independiente en materia de PLA/FT para los sujetos obligados del mercado de capitales (Resolución UIF 78/2023) debe realizarse al menos:",o:["Una vez al año","Cada seis meses","Cada tres años","Sólo cuando lo requiera la UIF"],a:0,e:"Revisión externa independiente: al menos una vez al año.",r:"M2 · P57"},
{id:"M2-67",m:2,q:"La Unidad de Información Financiera (UIF) puede actuar:",o:["Sólo en la Ciudad Autónoma de Buenos Aires","Sólo en las provincias adheridas por convenio","En cualquier jurisdicción del país","Sólo en jurisdicción federal y con orden judicial previa"],a:2,e:"La UIF puede actuar en cualquier jurisdicción del país.",r:"M2 · P58"},
{id:"M2-68",m:2,q:"Los activos involucrados en el proceso de Lavado de Activos:",o:["Pueden provenir de cualquier delito","Provienen sólo del narcotráfico","Provienen sólo de delitos contra la administración pública","Pueden provenir tanto de actividades lícitas como ilícitas"],a:0,e:"El lavado puede tener como origen cualquier delito; lo que no puede es tener origen lícito (eso es propio del FT).",r:"M2 · P59"},
{id:"M2-19",m:2,q:"Los Sujetos Obligados deberán conservar la documentación (respecto de la identificación, conocimiento y operaciones) del cliente durante un período mínimo de:",o:["3 años desde el cierre de la cuenta","1 año desde la última operación","Hasta la próxima supervisión de la UIF","10 años desde la finalización de la relación con el cliente"],a:3,e:"La guía da 10 años desde la finalización de la relación con el cliente. Ojo: para esta pregunta la guía da 10 años; en la P19 (documentación respaldatoria) da 5 años.",r:"M2 · P60"},
{id:"M2-94",m:2,q:"Los sujetos obligados que operan en el Mercado de Capitales deberán realizar el correspondiente Reporte de Operación Sospechosa ante:",o:["La Comisión Nacional de Valores","El mercado en el que operan","La Unidad de Información Financiera","El Ministerio Público Fiscal"],a:2,e:"Aunque su supervisor sea la CNV, el ROS se presenta ante la UIF.",r:"M2 · P61"},
{id:"M2-18",m:2,q:"Recibida la notificación de la Resolución de la UIF que dispone el congelamiento administrativo de bienes o dinero (Res. UIF 29/2013), el Sujeto Obligado dispone de ____ para informar el resultado de su aplicación, en el caso que haya congelado bienes o dinero:",o:["24 horas","10 días hábiles","30 días","60 días"],a:3,e:"60 días para informar el resultado del congelamiento, aunque la medida se aplica de inmediato.",r:"M2 · P62"},
{id:"M2-36",m:2,q:"Se entiende por Cliente según la Res. UIF 78/2023:",o:["Sólo quien tiene cuenta comitente abierta y activa","A toda persona humana, jurídica o estructura jurídica, nacional o extranjera, con la que se establece de manera ocasional o permanente una relación contractual de carácter financiero, económico o comercial","Quien opera por montos superiores al umbral fijado por la UIF","Únicamente el titular registral de los fondos"],a:1,e:"Incluye la relación ocasional, no sólo la permanente.",r:"M2 · P63"},
{id:"M2-37",m:2,q:"Según la Res. UIF 3/2014, cuando un sujeto obligado posee como cliente a otro sujeto obligado deberá:",o:["Solicitar Declaración Jurada sobre el cumplimiento de las disposiciones vigentes en materia de PLD/FT","Aplicar debida diligencia reforzada en todos los casos","Eximirlo de legajo","Reportar la relación a la UIF"],a:0,e:"Se le pide DDJJ de cumplimiento; no queda exento de legajo.",r:"M2 · P64"},
{id:"M2-34",m:2,q:"Según Res. 78/2023, los legajos deben confeccionarse para:",o:["Sólo clientes de riesgo alto","Sólo personas jurídicas","Todos los clientes","Sólo clientes que operen por encima de su cupo"],a:2,e:"Legajo para todos los clientes; lo que varía según el riesgo es la profundidad de la diligencia.",r:"M2 · P65"},
{id:"M2-69",m:2,q:"Señale cuál de las siguientes afirmaciones es correcta:",o:["Los fondos utilizados en el lavado de activos pueden provenir de actividades lícitas","El financiamiento del terrorismo utiliza exclusivamente fondos ilícitos","Los fondos utilizados en el lavado de activos provienen exclusivamente de actividades ilícitas","El lavado de activos sólo se configura cuando interviene dinero en efectivo"],a:2,e:"En el lavado el origen es siempre ilícito. El que puede usar fondos lícitos es el financiamiento del terrorismo.",r:"M2 · P66"},
{id:"M2-95",m:2,q:"Pueden ser Personas Expuestas Políticamente (PEPs), de conformidad con lo dispuesto por la Resolución UIF 192/2024:",o:["Los accionistas minoritarios de sociedades con oferta pública; los empleados de empresas privadas sin participación estatal; y los comitentes que operan montos elevados","Los asesores financieros independientes; los empleados de bancos privados; y los socios de sociedades de garantía recíproca","El personal del Poder Legislativo de la Nación; funcionarios o empleados de entidades autárquicas, bancos oficiales, obras sociales estatales, empresas del Estado o sociedades con participación estatal mayoritaria; y funcionarios o empleados públicos con poder de decisión en comisiones de adjudicación","Únicamente los jefes de Estado extranjeros y sus familiares directos"],a:2,e:"La guía lista esos tres grupos: personal del Poder Legislativo, funcionarios o empleados de entes estatales o con participación estatal mayoritaria, y quienes deciden en comisiones de adjudicación.",r:"M2 · P67"},
{id:"M2-47",m:2,q:"Conforme surge de la Resolución UIF 78/2023, los Regímenes Informativos a reportar ante UIF deberán informarse:",o:["De manera mensual: listado de cuentas comitentes diferenciando entre activos e inactivos, identificando las subcuentas de la cartera propia de la sociedad","De manera anual: detalle de las comisiones cobradas a cada comitente","De manera semestral: nómina de empleados capacitados en PLA/FT","De manera trimestral: resultado de la autoevaluación de riesgos"],a:0,e:"Régimen informativo mensual: listado de cuentas comitentes activas e inactivas, con las subcuentas de cartera propia identificadas.",r:"M2 · P68"},
{id:"M2-43",m:2,q:"Una Organización sin fines de lucro es cliente de una sociedad y recibe fondos de una donación. Con ellos compra Bonos (Legislación Local), que transfiere inmediatamente a una cuenta radicada en el exterior. El procedimiento de control a efectuar sería:",o:["Reportar de inmediato sin más análisis","Bloquear la cuenta hasta que la ONG presente su balance","Consultar a la CNV antes de ejecutar la orden","Determinar el origen de la donación y el destino de la cuenta a la cual son transferidos los fondos"],a:3,e:"Primero se profundiza: origen de la donación y destino de los fondos.",r:"M2 · P69"},
{id:"M2-71",m:2,q:"Una de las obligaciones del Sujeto Obligado conforme los incs. a y b del art. 21 de la Ley 25.246 y mod. es:",o:["Recabar documentación sólo de los clientes que superen un monto mínimo anual","Informar al cliente cuando su operación haya sido reportada a la UIF","Publicar anualmente ante la CNV la nómina de sus clientes","Recabar de sus clientes, requirentes o aportantes documentos que prueben fehacientemente su identidad, personería jurídica, domicilio, residencia y demás datos que se estipulen"],a:3,e:"Los incisos a y b del art. 21 imponen identificar al cliente con documentación fehaciente para cualquier tipo de actividad del sujeto obligado.",r:"M2 · P70"},
{id:"M2-96",m:2,q:"La Autoevaluación de Riesgo para un Sujeto Obligado inscripto en la categoría de Agente Asesor Global de Inversión podrá realizarse (Resolución UIF 78/2023):",o:["Cada tres años","Sólo al momento de inscribirse ante la CNV","Cada seis meses","Cada dos años"],a:3,e:"Para el AAGI la autoevaluación puede hacerse cada dos años, igual que para el Agente de Negociación.",r:"M2 · P71"},
{id:"M2-72",m:2,q:"Se entiende por debida diligencia:",o:["A los procedimientos de conocimiento aplicables a todos los Clientes, que se llevarán a cabo teniendo en cuenta los niveles de riesgo asignados a cada uno","Los procedimientos de conocimiento aplicables sólo a los clientes de riesgo alto","El análisis de solvencia crediticia del cliente antes de asignarle un cupo","La revisión anual del manual de prevención por un auditor externo"],a:0,e:"Aplica a todos los clientes; lo que cambia según el riesgo asignado es la intensidad (simplificada, media o reforzada).",r:"M2 · P72"},
{id:"M2-97",m:2,q:"Conforme las Normas CNV se consideran como Sujetos Obligados que actúan en el ámbito de Mercado de Capitales a:",o:["Únicamente los Agentes de Negociación y los Agentes de Liquidación y Compensación, incluidos los Participantes Directos","Agentes de Negociación, ALyC, Agentes de colocación y distribución de FCI u otros productos de inversión colectiva, Agentes Asesores Globales de Inversión, Fiduciarios financieros con oferta pública autorizada por la Comisión, Plataformas de Financiamiento Colectivo y Proveedores de Servicios de Activos Virtuales","Agentes Productores, Agentes de Negociación, ALyC Participantes Directos y Agentes Asesores Globales de Inversión","Sólo las entidades financieras autorizadas por el BCRA que actúen como custodios de valores negociables"],a:1,e:"La lista de la guía incluye AN, ALyC, colocadores de FCI, AAGI, fiduciarios financieros con oferta pública, PFC y PSAV. Los Agentes Productores y los ALyC Participantes Directos quedan afuera.",r:"M2 · P73"},
{id:"M2-38",m:2,q:"Conforme las Normas CNV no se consideran como Sujetos Obligados que actúan en el ámbito de Mercado de Capitales a:",o:["Los Agentes de Negociación y los Agentes Asesores Globales de Inversión","Los Agentes de Liquidación y Compensación Participantes Directos y los Agentes Productores","Las Plataformas de Financiamiento Colectivo y los Proveedores de Servicios de Activos Virtuales","Los fiduciarios financieros con oferta pública y los colocadores de FCI"],a:1,e:"No son sujetos obligados los ALyC Participantes Directos ni los Agentes Productores; el resto de las opciones sí lo son.",r:"M2 · P74"},
{id:"M2-39",m:2,q:"Los ALyC y quienes actúen en la colocación de FCI o de otros productos de inversión colectiva, en materia de recepción de fondos de sus Clientes deberán verificar que:",o:["Provengan de cualquier cuenta bancaria del país","Provengan de cuentas radicadas en el exterior a nombre del cliente","Sean depositadas en efectivo en la sede del agente","Sean efectuadas desde cuentas de titularidad o cotitularidad del cliente (CBU/CVU) abiertas en entidades del país autorizadas por el BCRA, que permitan la identificación y trazabilidad de la transferencia"],a:3,e:"Trazabilidad: el dinero debe venir de una cuenta del propio cliente en entidad autorizada por el BCRA.",r:"M2 · P75"},
{id:"M2-21",m:2,q:"El capital de una sociedad asciende a $10.000.000: Socio A $2.000.000, Socio B $300.000, Socio C $7.700.000. De acuerdo a la normativa vigente, determinar quiénes son los beneficiarios finales.",o:["Socio A y C","Sólo el Socio C","Socios A, B y C","Ninguno: no se alcanza el umbral"],a:0,e:"A = 20% y C = 77% superan el 10%. B = 3% no llega.",r:"M2 · P76"},
{id:"M2-46",m:2,q:"A los fines de acreditar el requisito de INTEGRIDAD ante los registros de la CNV se deberá presentar:",o:["Constancia de inscripción en el Registro de Idóneos","Certificado de antecedentes penales y Declaración Jurada de PLAFT","Título habilitante y certificado de idoneidad","Estados contables auditados"],a:1,e:"La integridad se acredita con el certificado de antecedentes penales y la DDJJ de PLAFT.",r:"M2 · P77"},
{id:"M2-82",m:2,q:"A los fines de acreditar el requisito de SOLVENCIA ante los registros de la CNV se deberá presentar:",o:["Estados contables auditados de los últimos tres ejercicios","Título habilitante y certificado de idoneidad","Informe de antecedentes comerciales actualizado","Constancia de inscripción en el Registro de Idóneos"],a:2,e:"La CNV pide integridad, idoneidad y solvencia; la solvencia se acredita con el informe de antecedentes comerciales actualizado.",r:"M2 · P78"},
{id:"M2-33",m:2,q:"El manual de prevención de Lavado de Activos y Financiación del Terrorismo deberá ser revisado:",o:["Mensualmente","Semestralmente","Anualmente","Cada cinco años"],a:2,e:"La guía indica revisión anual del manual.",r:"M2 · P79"},
{id:"M2-73",m:2,q:"Respecto del Código de Conducta:",o:["Sólo obliga al Oficial de Cumplimiento y al órgano de administración, y basta con publicarlo en la web del Sujeto Obligado, sin constancia de conocimiento del personal","Es optativo para el Sujeto Obligado y sus incumplimientos al Sistema PLA/FT no se consideran falta interna, sino materia exclusiva de la UIF","Debe ser aprobado por la CNV y limitarse a las reglas comerciales de atención al cliente, sin referencias al Sistema de Prevención de LA/FT","Debe contener los principios rectores y valores de integridad y adecuada capacidad técnica; incluir el carácter obligatorio de las políticas, procedimientos y controles del Sistema PLA/FT, a cumplir por directores, gerentes, empleados y colaboradores; contar con constancia fehaciente de su conocimiento; y contemplar todo incumplimiento al Sistema PLA/FT como falta interna"],a:3,e:"La guía da cuatro puntos: principios y valores, obligatoriedad del sistema PLA/FT para todo el personal, constancia fehaciente de conocimiento y el incumplimiento como falta interna.",r:"M2 · P80"},
{id:"M2-22",m:2,q:"El capital de una sociedad asciende a $5.000.000: Socio A $250.000, Socio B $500.000, Socio C $2.500.000, Socio D $1.750.000. De acuerdo a la normativa vigente determinar quiénes son los beneficiarios finales.",o:["Socios C y D","Socio B, C y D","Todos los socios","Sólo el Socio C"],a:1,e:"B = 10% (llega al mínimo), C = 50%, D = 35%. A = 5% queda afuera.",r:"M2 · P81"},
{id:"M2-74",m:2,q:"El plan de capacitación en materia de Lavado de Activos y Financiación del Terrorismo deberá contener:",o:["La normativa nacional y los estándares internacionales vigentes sobre prevención de LA/FT, y la definición de los delitos de LA/FT","Únicamente la operatoria comercial de los productos que ofrece el agente","Las estrategias de inversión recomendadas para cada perfil de riesgo","Sólo el contenido del manual interno, sin referencias a estándares internacionales"],a:0,e:"El plan de capacitación incluye normativa nacional, estándares internacionales vigentes y la definición de los delitos de LA y FT.",r:"M2 · P82"},
{id:"M2-27",m:2,q:"Son obligaciones del Oficial de Cumplimiento:",o:["Aprobar las operaciones de los clientes de riesgo alto y fijar su cupo operativo anual","Auditar los estados contables del sujeto obligado y firmar su balance","Proponer las políticas, procedimientos y controles para administrar y mitigar los riesgos de LA/FT, y atender los requerimientos de información de la UIF y la CNV","Definir los activos en los que puede operar cada cliente según su perfil"],a:2,e:"La guía le asigna proponer las políticas y controles de mitigación del riesgo LA/FT y atender los requerimientos de la UIF y la CNV.",r:"M2 · P83"},
{id:"M2-28",m:2,q:"Dos o más sujetos obligados vinculados entre sí por una relación de control o pertenecientes a una misma organización societaria:",o:["Deben designar un oficial de cumplimiento por cada entidad","Pueden designar un único Oficial de Cumplimiento titular y suplente, y compartir legajos de Clientes","No pueden compartir información por el secreto bursátil","Deben unificar su matriz de riesgo ante la CNV"],a:1,e:"El grupo puede unificar oficial de cumplimiento (titular y suplente) y compartir legajos.",r:"M2 · P84"},
{id:"M2-29",m:2,q:"El Comité de Prevención de Lavado de Activos y Financiación del Terrorismo puede estar integrado por:",o:["Oficial de Cumplimiento y funcionarios del primer nivel gerencial cuyas funciones se encuentren relacionadas con riesgos de LA/FT","Únicamente directores independientes","El auditor externo y el síndico","Representantes de la UIF y de la CNV"],a:0,e:"Oficial de cumplimiento + primera línea gerencial relacionada con el riesgo LA/FT.",r:"M2 · P85"},
{id:"M2-75",m:2,q:"Los Sujetos Obligados pueden depender de otros Sujetos Obligados para la ejecución de las medidas de Debida Diligencia del Cliente, únicamente respecto de:",o:["El monitoreo de operaciones y la emisión del Reporte de Operaciones Sospechosas","La autoevaluación de riesgos y la declaración de tolerancia al riesgo","La designación del Oficial de Cumplimiento y la aprobación del manual","La identificación y verificación del Cliente; la identificación y verificación del beneficiario final; y la comprensión del propósito y carácter de la relación comercial"],a:3,e:"Sólo esas tres medidas pueden apoyarse en otro sujeto obligado: identificar/verificar al cliente, identificar/verificar al beneficiario final y comprender el propósito de la relación.",r:"M2 · P86"},
{id:"M2-76",m:2,q:"De acuerdo con el art. 4° bis de la Ley 25.246 y mod. y la Resolución UIF 49/2024, son Proveedores de Servicios de Activos Virtuales toda persona humana o jurídica que, como negocio, realice para o en nombre de terceros una o más de las siguientes actividades:",o:["Otorgar préstamos en pesos a personas humanas","Calificar el riesgo crediticio de emisoras de obligaciones negociables","Invertir fondos propios en activos virtuales para su propia cartera","Custodia y/o administración de activos virtuales o instrumentos que permitan el control sobre los mismos"],a:3,e:"La custodia y/o administración de activos virtuales para terceros es una de las actividades que definen al PSAV.",r:"M2 · P87"},
{id:"M2-23",m:2,q:"Considerando que la matriz de riesgo arroja un nivel de riesgo ALTO para un Cliente, la debida diligencia a aplicar deberá ser:",o:["Aplicar medidas de debida diligencia reforzada y actualizar el legajo cada 3 años","Aplicar medidas de debida diligencia media y actualizar el legajo cada 1 año","Aplicar medidas de debida diligencia reforzada y actualizar el legajo cada 1 año","Aplicar la misma debida diligencia que para el resto de los clientes"],a:2,e:"Riesgo alto: debida diligencia reforzada y legajo actualizado cada 1 año.",r:"M2 · P88"},
{id:"M2-98",m:2,q:"Considerando que la matriz de riesgo arroja un nivel de riesgo BAJO para un Cliente, la debida diligencia a aplicar deberá ser:",o:["Aplicar medidas de debida diligencia simplificada y actualizar el legajo cada 5 años","Aplicar medidas de debida diligencia simplificada y actualizar el legajo cada 1 año","Aplicar medidas de debida diligencia reforzada y actualizar el legajo cada 5 años","No aplicar debida diligencia hasta que cambie el nivel de riesgo"],a:0,e:"Riesgo bajo: debida diligencia simplificada y legajo actualizado cada 5 años. Aun con riesgo bajo, la diligencia se aplica.",r:"M2 · P89"},
{id:"M2-99",m:2,q:"Conforme la Resolución 49/2024 se considera Proveedor de Servicios de Activos Virtuales:",o:["Sólo a la persona jurídica que, con autorización del BCRA, emite activos virtuales y los vende a sus propios clientes bancarios","A cualquier persona humana o jurídica que, como negocio, realiza para o en nombre de otra: i. intercambio entre activos virtuales y monedas de curso legal; ii. intercambio entre formas de activos virtuales; iii. transferencia de activos virtuales; iv. custodia y/o administración de activos virtuales o instrumentos que permitan su control; y v. servicios financieros relacionados con la oferta y/o venta de un activo virtual","A cualquier persona humana que invierte sus propios ahorros en activos virtuales, sin actuar para terceros","Sólo a los mercados autorizados por la CNV que listan valores negociables tokenizados"],a:1,e:"La clave es hacerlo como negocio y para o en nombre de terceros, en alguna de las cinco actividades que enumera la guía.",r:"M2 · P90"},
{id:"M2-100",m:2,q:"El Sujeto Obligado debe realizar una declaración de tolerancia al riesgo, debidamente fundada y aprobada por el órgano de administración o la máxima autoridad, que deberá ser enviada a:",o:["Sólo a la UIF","Sólo a la CNV","La UIF y la Comisión Nacional de Valores","El BCRA y el mercado donde opera"],a:2,e:"La declaración de tolerancia al riesgo se envía a los dos: la UIF y la CNV.",r:"M2 · P91"},
{id:"M2-77",m:2,q:"El Sujeto Obligado deberá adoptar, entre otras y como mínimo, políticas, procedimientos y controles a los efectos de:",o:["Identificar a los beneficiarios finales de sus clientes sólo al inicio de la relación","Identificar, verificar y conocer en forma continua a los beneficiarios finales de sus clientes","Verificar a los beneficiarios finales únicamente de los clientes extranjeros","Maximizar la rentabilidad de las carteras de sus clientes"],a:1,e:"El conocimiento del beneficiario final es continuo, no se agota en la apertura de la cuenta.",r:"M2 · P92"},
{id:"M2-42",m:2,q:"Conforme la Resolución 49/2024 se considera como Activos Virtuales a:",o:["Toda criptomoneda emitida por un banco central","Todo valor negociable listado en un mercado autorizado","Cualquier token emitido en el exterior","La representación digital de valor que se puede comercializar y/o transferir digitalmente y utilizar para pagos o inversiones"],a:3,e:"Definición amplia: representación digital de valor, comercializable/transferible, usada para pagos o inversiones.",r:"M2 · P93"},
{id:"M2-78",m:2,q:"El órgano de administración o máxima autoridad del Sujeto Obligado será el responsable de:",o:["Realizar personalmente la revisión externa independiente","Presentar los Reportes de Operaciones Sospechosas ante la CNV","Entender y tomar en cuenta los riesgos de LA/FT/FP al establecer sus objetivos comerciales","Delegar en el mercado la gestión del riesgo de LA/FT"],a:2,e:"El órgano de administración tiene que considerar el riesgo de LA/FT/FP cuando fija los objetivos comerciales.",r:"M2 · P94"},
{id:"M2-79",m:2,q:"Conforme la Resolución 49/2024 los Proveedores de Servicios de Activos Virtuales deberán realizar de forma sistemática los siguientes reportes:",o:["Reporte sistemático anual (RSA), entre el 2 de enero y el 15 de marzo inclusive de cada año, respecto del año calendario anterior","Reporte sistemático anual (RSA), entre el 1 de febrero y el 30 de abril de cada año, respecto del año calendario anterior","Reporte sistemático semestral, dentro de los 15 días de cerrado cada semestre","Reporte sistemático anual (RSA), entre el 2 de enero y el 31 de mayo de cada año, respecto del año en curso"],a:0,e:"RSA: del 2 de enero al 15 de marzo inclusive, sobre el año calendario anterior.",r:"M2 · P95"},
{id:"M2-80",m:2,q:"En el Informe técnico de autoevaluación de riesgos, el Sujeto Obligado deberá:",o:["Limitarse a los factores de riesgo de su línea de negocio principal, excluir la información de la UIF para preservar su independencia y conservarlo sólo en poder del revisor externo","Considerar los factores de riesgo en cada línea de negocio, con su riesgo inherente y la mitigación a aplicar; incorporar la información de la UIF u otras autoridades; considerar las Evaluaciones Nacionales de Riesgo de LA/FT/FP y otros documentos del sector; y ser autosuficiente, documentado y conservado en el domicilio registrado ante la UIF","Tomar como único insumo la opinión del Oficial de Cumplimiento y enviarlo a la CNV para su aprobación previa","Basarse exclusivamente en los estándares del GAFI, sin considerar las Evaluaciones Nacionales de Riesgo, y publicarse en la web del Sujeto Obligado"],a:1,e:"La guía da cuatro requisitos: factores de riesgo por línea de negocio, información de la UIF y otras autoridades, Evaluaciones Nacionales de Riesgo, y un informe autosuficiente conservado en el domicilio registrado ante la UIF.",r:"M2 · P96"},
{id:"M2-45",m:2,q:"Los Reportes de Operaciones Sospechosas deberán:",o:["Estar fundados y contener una descripción de las razones y/o inusualidades por las cuales se considera que la operación presenta tal carácter","Limitarse a los datos de identificación del cliente","Ser aprobados previamente por la CNV","Acompañarse de una denuncia penal"],a:0,e:"Un ROS sin fundamentación y sin descripción de la inusualidad es un reporte defectuoso.",r:"M2 · P97"},
{id:"M2-101",m:2,q:"Al Comitente A le fue asignado un perfil de riesgo Alto con un cupo operativo anual de $6.000.000. En el mes de mayo dicho Comitente opera por $900.000. En este caso el ALyC deberá:",o:["No hacer nada, porque la operación está dentro del cupo anual","Reportarlo de inmediato a la UIF sin análisis previo","Solicitar documentación de respaldo","Bajarle el perfil de riesgo a Medio"],a:2,e:"Para la guía, con un cliente de riesgo alto el ALyC debe solicitar documentación de respaldo, aunque el monto esté dentro del cupo.",r:"M2 · P98"},
{id:"M2-44",m:2,q:"Al Comitente A le fue asignado un perfil de riesgo Alto con un cupo operativo anual de $6.000.000. En el mes de mayo ingresa dinero en la Cuenta Comitente por $18.000.000 y, ante el requerimiento del ALyC, informa que proviene de la venta de su automóvil. En este caso el ALyC deberá:",o:["Aceptar la explicación verbal y registrarla","Reportar automáticamente a la UIF sin análisis previo","Devolver los fondos a la cuenta de origen","Solicitar documentación de respaldo"],a:3,e:"La declaración del cliente no alcanza: hay que respaldarla documentalmente y recién después decidir si se reporta.",r:"M2 · P99"},
{id:"M2-102",m:2,q:"En el Registro de Operaciones Inusuales solo debe asentarse:",o:["Solo la operación que finalmente se reportó a la UIF, con su fecha de envío","Múltiples elementos simultáneamente, entre ellos: datos completos del cliente, detalle de la operación, motivos por los que fue considerada inusual, análisis realizado, documentación respaldatoria, fecha de detección, decisión final (si se reporta o no), responsable interviniente y conclusiones motivadas","Solo el nombre del cliente y el monto de la operación detectada","Solo la decisión final del Oficial de Cumplimiento, sin el análisis que la sustenta"],a:1,e:"Pese al \"solo\" del enunciado, la guía dice que se asientan múltiples elementos a la vez, desde los datos del cliente hasta la decisión y sus conclusiones.",r:"M2 · P71 bis"},
{id:"M2-103",m:2,q:"Ley 27.739: ámbito sancionatorio. ¿Quién aplica sanciones administrativas por incumplimientos en PLA/FT?",o:["CNV","BCRA","Poder Judicial","UIF"],a:3,e:"Las sanciones administrativas por incumplimientos en PLA/FT las aplica la UIF, no la CNV.",r:"M2 · P72 bis"},
{id:"M2-104",m:2,q:"El plazo para enviar un Reporte de Operaciones Sospechosas de Lavado de Activos se rige por:",o:["Ley 26.831 y Normas CNV Título XI","Ley 27.739 y UIF 56/2024","Decreto 918/2012 y UIF 3/2014","Ley 25.345 y UIF 192/2024"],a:1,e:"El plazo del ROS de LA sale de la Ley 27.739 y de la Res. UIF 56/2024 (la de plazos de ROS).",r:"M2 · P73 bis"},
{id:"M2-105",m:2,q:"UIF 56/2024. Cuando se trata de Financiamiento de Terrorismo con personas/bienes listados por ONU, el Reporte de Operaciones Sospechosas debe enviarse:",o:["Sin demora","Dentro de las 24 horas hábiles","Dentro de los 30 días corridos","Junto con el reporte sistemático anual"],a:0,e:"Con personas o bienes designados por la ONU no hay plazo que esperar: el ROS va sin demora.",r:"M2 · P74 bis"},
{id:"M2-106",m:2,q:"UIF 78/2023. La Revisión Externa Independiente para SO del mercado de capitales debe realizarse al menos:",o:["Semestralmente","Cada tres años","Anualmente","Sólo cuando lo requiera la CNV"],a:2,e:"La revisión externa independiente es, como mínimo, anual.",r:"M2 · P75 bis"},
{id:"M2-107",m:2,q:"UIF 78/2023. La declaración de tolerancia al riesgo debe enviarse a:",o:["UIF y Comisión Nacional de Valores","Sólo a la Comisión Nacional de Valores","Sólo a la UIF","BCRA y Comisión Nacional de Valores"],a:0,e:"Se envía a la UIF y a la CNV, igual que el informe técnico de autoevaluación de riesgos.",r:"M2 · P76 bis"},
{id:"M2-70",m:2,q:"Según UIF 192/2024, ¿cuál de las siguientes sí integra la definición de PEP?",o:["El accionista minoritario de una sociedad con oferta pública","El empleado administrativo de una empresa privada sin participación estatal","El comitente que opera montos elevados en un mercado autorizado","Autoridades y funcionarios de la APN"],a:3,e:"Las autoridades y funcionarios de la Administración Pública Nacional integran la definición de PEP de la Res. UIF 192/2024.",r:"M2 · P77 bis"},
{id:"M2-108",m:2,q:"UIF 49/2024. Se considera Proveedores de Servicios de Activos Virtuales a Personas Humanas o Jurídicas que, como negocio, realicen una o más de las siguientes actividades incluyendo:",o:["Emisión de moneda de curso legal, custodia de títulos públicos y calificación de riesgo","Minería de activos virtuales para cartera propia, sin actuar para terceros","Transferencia, custodia, administración, participación y servicios financieros en la oferta o venta de Activos Virtuales","Intermediación exclusiva en valores negociables con oferta pública autorizada por la CNV"],a:2,e:"Transferencia, custodia, administración y servicios financieros vinculados a la oferta o venta de AV, hechos como negocio, definen al PSAV.",r:"M2 · P78 bis"},
{id:"M2-109",m:2,q:"UIF 49/2024: \"Activo Virtual\" es:",o:["Representación digital de valor que puede comercializarse/transferirse y utilizarse para pagos o inversiones","Todo valor negociable escritural registrado en Caja de Valores","La moneda de curso legal cuando se transfiere por medios electrónicos","Cualquier saldo en una billetera virtual expresado en pesos"],a:0,e:"Activo virtual es una representación digital de valor que se comercializa o transfiere y se usa para pagos o inversiones.",r:"M2 · P79 bis"},
{id:"M2-110",m:2,q:"UIF 78/2023. Los SO pueden depender de terceros (CDD) para:",o:["Emitir el ROS, monitorear operaciones y aprobar el manual","Designar al Oficial de Cumplimiento y fijar la tolerancia al riesgo","Realizar la revisión externa independiente y la autoevaluación de riesgos","Verificar beneficiario final; identificar/verificar cliente; y comprender propósito/naturaleza de la relación"],a:3,e:"Sólo esas tres medidas de debida diligencia pueden apoyarse en un tercero sujeto obligado.",r:"M2 · P80 bis"},
{id:"M2-81",m:2,q:"UIF 78/2023. El registro de operaciones inusuales debe contener al menos:",o:["Sólo los datos de identificación del cliente","Descripción, análisis, documentación soporte, decisión y fundamento","Únicamente las operaciones que finalmente se reportaron a la UIF","Sólo el monto y la fecha de la operación"],a:1,e:"El registro no es una lista de operaciones: tiene que dejar la descripción, el análisis, el soporte documental y la decisión fundada.",r:"M2 · P81 bis"},
{id:"M2-111",m:2,q:"UIF 78/2023: ¿cuál de los siguientes es mensual para SO de mercado de capitales?",o:["Informe técnico de autoevaluación de riesgos","Declaración de tolerancia al riesgo","Nómina de cuentas comitentes (activas/inactivas) y, cuando corresponda, transferencias internacionales de VN","Revisión externa independiente"],a:2,e:"Lo mensual es la nómina de cuentas comitentes activas e inactivas y, si corresponde, las transferencias internacionales de valores negociables.",r:"M2 · P82 bis"},
{id:"M2-112",m:2,q:"Título XI CNV. Los ALyC y colocadores de FCI deben recibir fondos de clientes exclusivamente desde:",o:["CBU/CVU de titularidad o cotitularidad del cliente en entidades autorizadas por BCRA","Cualquier CBU/CVU del país, aunque sea de un tercero","Cuentas del cliente en entidades del exterior","Efectivo entregado en la sede del agente"],a:0,e:"Los fondos tienen que venir de una cuenta del propio cliente (o cotitular) en entidad autorizada por el BCRA, para que haya trazabilidad.",r:"M2 · P83 bis"}
);
